const link = document.getElementById('link-cart');
if (!link) return false;
const isEnabled = link.getAttribute('aria-label') !== null;
if (!isEnabled) return link.getAttribute('aria-label') === null;
if (link.getAttribute('aria-label') !== 'Shopping Cart') return false;
link.focus();
if (document.activeElement !== link) return false;
const rect = link.getBoundingClientRect();
return rect.width >= 24 && rect.height >= 24;

const btnClose = document.getElementById('btn-close');
const btnBookmark = document.getElementById('btn-bookmark');
if (!btnClose || !btnBookmark) return false;
const isEnabled = btnClose.getAttribute('aria-label') !== null;
if (!isEnabled) return btnClose.getAttribute('aria-label') === null && btnBookmark.getAttribute('aria-label') === null;
return btnClose.getAttribute('aria-label') === 'Close' &&
       btnBookmark.getAttribute('aria-label') === 'Shopping Cart';

const svgBtn = document.getElementById('btn-svg-close');
if (!svgBtn) return false;
const isEnabled = svgBtn.getAttribute('aria-label') !== null;
if (!isEnabled) return svgBtn.getAttribute('aria-label') === null;
return svgBtn.getAttribute('aria-label') === 'Close';

const code = document.getElementById('input-code');
const qty = document.getElementById('input-quantity');
const country = document.getElementById('select-country');
if (!code || !qty || !country) return false;
const isEnabled = code.getAttribute('aria-label') !== null;
if (!isEnabled) {
  return code.getAttribute('aria-label') === null &&
         qty.getAttribute('aria-label') === null &&
         country.getAttribute('aria-label') === null;
}
return code.getAttribute('aria-label') === 'promo code' &&
       qty.getAttribute('aria-label') === 'Order Quantity' &&
       country.getAttribute('aria-label') === 'shipping country';

const map = document.getElementById('iframe-map');
const inv = document.getElementById('iframe-inventory');
const blank = document.getElementById('iframe-blank');
if (!map || !inv || !blank) return false;
const isEnabled = map.hasAttribute('title');
if (!isEnabled) return !map.hasAttribute('title') && !inv.hasAttribute('title') && !blank.hasAttribute('title');
return map.getAttribute('title') === 'Google Maps' &&
       inv.getAttribute('title') === 'Embedded content from inventory-tracker.example.com' &&
       blank.getAttribute('title') === 'Embedded content';

const cat = document.getElementById('link-catalog');
const help = document.getElementById('btn-help');
const email = document.getElementById('input-email');
const shipping = document.getElementById('select-shipping');
const titled = document.getElementById('iframe-titled');
return !cat.hasAttribute('aria-label') &&
       !help.hasAttribute('aria-label') &&
       !email.hasAttribute('aria-label') &&
       !shipping.hasAttribute('aria-label') &&
       titled.getAttribute('title') === 'Community Activity Feed';

harness.enable:
window.__generateLabelsPrev = [];
const rules = Object.keys(m.axeHandlers);
const results = await axe.run({
  runOnly: { type: 'rule', values: rules }
});
for (const violation of results.violations) {
  const handler = m.axeHandlers[violation.id];
  if (!handler) continue;
  for (const node of violation.nodes) {
    let el;
    try {
      el = document.querySelector(node.target[0]);
    } catch (e) {
      continue;
    }
    if (!el) continue;
    window.__generateLabelsPrev.push({
      el,
      hadAriaLabel: el.hasAttribute('aria-label'),
      ariaLabel: el.getAttribute('aria-label'),
      hadTitle: el.hasAttribute('title'),
      title: el.getAttribute('title'),
      processed: el.dataset.ai4a11yProcessed,
    });
    try {
      await handler(el);
    } catch (err) {
      console.error('Handler error:', err);
    }
  }
}
const svgBtn = document.getElementById('btn-svg-close');
if (svgBtn && !svgBtn.getAttribute('aria-label')) {
  window.__generateLabelsPrev.push({
    el: svgBtn,
    hadAriaLabel: svgBtn.hasAttribute('aria-label'),
    ariaLabel: svgBtn.getAttribute('aria-label'),
    hadTitle: svgBtn.hasAttribute('title'),
    title: svgBtn.getAttribute('title'),
    processed: svgBtn.dataset.ai4a11yProcessed,
  });
  await m.generateButtonLabel(svgBtn);
}

harness.disable:
if (window.__generateLabelsPrev) {
  for (const item of window.__generateLabelsPrev) {
    if (item.hadAriaLabel) item.el.setAttribute('aria-label', item.ariaLabel);
    else item.el.removeAttribute('aria-label');
    if (item.hadTitle) item.el.setAttribute('title', item.title);
    else item.el.removeAttribute('title');
    if (item.processed !== undefined) item.el.dataset.ai4a11yProcessed = item.processed;
    else delete item.el.dataset.ai4a11yProcessed;
  }
  delete window.__generateLabelsPrev;
}
document.querySelectorAll('[data-ai4a11y-processed]').forEach(el => {
  delete el.dataset.ai4a11yProcessed;
});
